function decodeImg(entry, w = S, h = S) {
  const im = new Img(w, h);
  const [pal, b64] = entry;
  const bin = atob(b64);
  const d = im.d;
  for (let i = 0; i < bin.length; i++) {
    const idx = bin.charCodeAt(i);
    if (idx === 0) continue;
    const c = pal[idx - 1];
    const o = i * 4;
    d[o] = (c >>> 24) & 255;
    d[o + 1] = (c >>> 16) & 255;
    d[o + 2] = (c >>> 8) & 255;
    d[o + 3] = c & 255;
  }
  return im;
}

