const SUN_DATA = [[255,16843007,33685759,50528767,50528511,67371519,84214271,101057279,101057023,117900031,134743039,151585791,168428799,168428543,185271551,218957311,235800063,269485823,303171583,320014335,202114303,336857343,353700095,387385855,286328831,437914367,454757375,454757119,370542847,404228607,505285887,522128639,538971647,421071615,471600127,572657407,589500159,606342911,640028671,656871423,673714431,4292168447,4294945535,4294957567],""];
const MOON_DATA = [[255,511,66303,16909311,66559,16909567,16909823,33752831,16910079,33753087,50596095,50661887,67504895,50662143,67505151,84348415,84414207,101257471,118100735,118166527,67505407,135009535,135009791,151853055,118100479,168762111,185605119,168762367,135010047,151853311,202448639,202514431,219357439,168696319,185605375,236200703,236200959,236266751,253110015,253110271,269953279,3655663615,2425857535,1347839743,1600617215,2948123903,1954386943,253044223],""];

const cache = new Map();

export function getTex(name) {
  let im = cache.get(name);
  if (im) return im;
  const key = ALIAS[name] || name;
  const entry = DATA[key];
  if (entry) {
    im = decodeImg(entry);
  } else {
    console.warn('missing texture painter:', name);
    im = new Img();
    im.each((x, y) => ((x >> 2) + (y >> 2)) & 1 ? 0xff00ff : 0x000000);
  }
  cache.set(name, im);
  return im;
}

export function sunImage() {
  return decodeImg(SUN_DATA, 32, 32);
}

export function moonImage() {
  return decodeImg(MOON_DATA, 32, 32);
}

// RGBA data for the block array texture (one 16x16 layer per TEX entry).
export function buildArrayData() {
  const out = new Uint8Array(TEX.length * S * S * 4);
  TEX.forEach((name, layer) => {
    const im = getTex(name);
    const d = new Uint8ClampedArray(im.d);
    // give fully transparent texels the average opaque colour so mipmaps don't darken edges
    let r = 0, g = 0, b = 0, n = 0;
    for (let i = 0; i < d.length; i += 4) if (d[i + 3] > 0) { r += d[i]; g += d[i + 1]; b += d[i + 2]; n++; }
    if (n > 0 && n < S * S) {
      r = (r / n) | 0; g = (g / n) | 0; b = (b / n) | 0;
      for (let i = 0; i < d.length; i += 4) if (d[i + 3] === 0) { d[i] = r; d[i + 1] = g; d[i + 2] = b; }
    }
    out.set(d, layer * S * S * 4);
  });
  return out;
}
